import re
import urllib.request
import json
# Constants
IP_REGEX = r'[0-9]+(?:\.[0-9]+){3}'
def task_func(API_URL):
    try:
        with urllib.request.urlopen(API_URL) as response:
            content = response.read().decode('utf-8', errors='ignore')
    except Exception as e:
        raise Exception(str(e))
    ip_text = content
    try:
        data = json.loads(content)
        if isinstance(data, dict):
            for v in data.values():
                if isinstance(v, str) and re.fullmatch(IP_REGEX, v):
                    return v
            text_candidates = []
            for v in data.values():
                if isinstance(v, str):
                    text_candidates.append(v)
            if text_candidates:
                ip_text = ' '.join(text_candidates)
        elif isinstance(data, str):
            ip_text = data
    except Exception:
        ip_text = content
    match = re.search(IP_REGEX, ip_text)
    if match:
        return match.group(0)
    raise Exception('Unable to determine public IP address')
